// ====== CREDENCIAIS SHOPEE (cole aqui depois da aprovacao) ======
const APP_ID = '<SEU_APP_ID>';   // dica: melhor usar $env.SHOPEE_APP_ID
const SECRET = '<SEU_SECRET>';   // dica: melhor usar $env.SHOPEE_SECRET
// ================================================================

const timestamp = Math.floor(Date.now() / 1000);

// "Produtos em alta / mais vendidos" -> sortType: 2 (Most sold)
// listType: 0=Recomendado 1=Maior comissao 2=Top performance
const query = '{ productOfferV2(sortType: 2, page: 1, limit: 30) { nodes { itemId productName priceMin priceMax priceDiscountRate sales ratingStar commissionRate commission imageUrl shopName offerLink productLink } pageInfo { page limit hasNextPage } } }';

const payload = JSON.stringify({ query });

// Assinatura = SHA256(AppId + Timestamp + Payload + Secret)
const signBase = APP_ID + timestamp + payload + SECRET;

return [{ json: { appId: APP_ID, timestamp, payload, signBase } }];

const resp = $input.first().json;
const lista = (resp && resp.data && resp.data.productOfferV2 && resp.data.productOfferV2.nodes) || [];
if (!lista.length) {
  throw new Error('Shopee nao retornou ofertas. Resposta: ' + JSON.stringify(resp).slice(0, 600));
}

// Memoria entre execucoes: nao repetir itens ja postados
const store = $getWorkflowStaticData('global');
store.posted = store.posted || [];

const frescos = lista.filter(n => !store.posted.includes(n.itemId));
const pool = frescos.length ? frescos : lista;

// Dentre os disponiveis, prioriza a MAIOR comissao pra voce
pool.sort((a, b) => (parseFloat(b.commissionRate) || 0) - (parseFloat(a.commissionRate) || 0));
const p = pool[0];

store.posted.push(p.itemId);
if (store.posted.length > 500) store.posted = store.posted.slice(-500);

const preco = (p.priceMin === p.priceMax)
  ? ('R$ ' + p.priceMin)
  : ('R$ ' + p.priceMin + ' - R$ ' + p.priceMax);
const desconto = p.priceDiscountRate ? ('🔥 ' + p.priceDiscountRate + '% OFF') : '';

const caption = [
  '🛍️ <b>' + p.productName + '</b>',
  '',
  desconto,
  '💰 ' + preco,
  '⭐ ' + (p.ratingStar || '-') + '   |   📦 ' + (p.sales || 0) + ' vendidos',
  '',
  '👉 <a href="' + p.offerLink + '">COMPRAR NA SHOPEE</a>'
].filter(Boolean).join('\n');

return [{ json: { caption, imageUrl: p.imageUrl, offerLink: p.offerLink, itemId: p.itemId } }];
